async function fixedDashboard(){try{const d=await api('/api/dashboard?date='+dateISO());const progress=d.target?Math.min(100,d.today.sales/d.target*100):0;const attention=d.attention||[];$('#app').innerHTML=shell('Owner Dashboard',`<div class="grid kpis"><div class="card kpi"><div class="label">Today's Sales</div><div class="value">${money(d.today.sales)}</div><div class="sub">${d.today.bills} bills • avg ${money(d.today.avg_bill)}</div></div><div class="card kpi"><div class="label">Gross Profit</div><div class="value">${money(d.today.gross_profit)}</div><div class="sub">${num(d.today.gross_margin)}% margin</div></div><div class="card kpi"><div class="label">Today's Expenses</div><div class="value">${money(d.expenses)}</div><div class="sub">Net ${money(d.today.gross_profit-d.expenses)}</div></div><div class="card kpi"><div class="label">Low Stock</div><div class="value">${d.low_stock}</div><div class="sub">Products needing refill</div></div></div><br><div class="grid two"><div class="card hero"><div class="between"><div><div class="small muted">TODAY'S SALES PROGRESS</div><div class="value">${money(d.today.sales)}</div><div class="small">Target ${money(d.target)} • Remaining ${money(Math.max(0,d.target-d.today.sales))}</div></div><span class="tag">${num(progress)}%</span></div><br><div class="progress"><div style="width:${progress}%"></div></div><br><div class="small muted">vs yesterday: ${d.today.sales>=d.yesterday.sales?'▲':'▼'} ${money(Math.abs(d.today.sales-d.yesterday.sales))}</div></div><div class="card"><h3>Inventory snapshot</h3><div class="grid two"><div><div class="small muted">At cost</div><strong>${money(d.inventory_cost)}</strong></div><div><div class="small muted">Low stock</div><strong>${d.low_stock}</strong></div><div><div class="small muted">Bills today</div><strong>${d.today.bills}</strong></div></div></div></div><br><div class="card"><h3>Owner attention</h3><div class="grid">${attention.length?attention.map(x=>`<div class="between notice ${x.stock<=0?'bad':'warn'}"><span><strong>${esc(x.name)}</strong><br><span class="small muted">${esc(x.sku)} • Refill at ${num(x.reorder_level)} units</span></span><strong>${num(x.stock)} left</strong></div>`).join(''):'<div class="notice good">All products have sufficient stock.</div>'}</div></div>`)}catch(e){$('#app').innerHTML=shell('Dashboard',`<div class="notice bad">${esc(e.message)}</div>`)}}
function fixedEnsureToast(){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}return t}
function fixedToast(msg){const t=fixedEnsureToast();t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function ensureToast(){return fixedEnsureToast()}
function roundCurrency(value){return Math.round((Number(value)||0)*100)/100}
function compareProductId(a,b){return String(a.sku||'').localeCompare(String(b.sku||''),undefined,{numeric:true,sensitivity:'base'})||Number(a.id)-Number(b.id)}
function sortProductsById(products){return [...products].sort(compareProductId)}
function cartSubtotal(){return roundCurrency((state.cart||[]).reduce((sum,it)=>{const p=state.products.find(x=>x.id===it.product_id);return sum+Number(it.unit_price??p?.default_unit_price??0)*Number(it.qty||0)},0))}
function billDiscountShares(amount,lines){const cents=Math.round(amount*100),weights=lines.map(x=>Math.max(0,Math.round(x*100))),total=weights.reduce((a,x)=>a+x,0);if(!cents||!total)return weights.map(()=>0);const shares=weights.map(x=>Math.floor(cents*x/total));let remainder=cents-shares.reduce((a,x)=>a+x,0);const order=weights.map((x,i)=>({i,r:(cents*x)%total})).sort((a,b)=>b.r-a.r||a.i-b.i);for(const entry of order.slice(0,remainder))shares[entry.i]++;return shares.map(x=>x/100)}
function activeBillDiscount(){const subtotal=cartSubtotal();state.billDiscount=Math.min(subtotal,Math.max(0,roundCurrency(state.billDiscount||0)));return state.billDiscount}
function discountCalcLine(it){const p=state.products.find(x=>x.id===it.product_id);if(!p)return {p:{name:'',sku:''},price:0,gross:0,disc:0,taxable:0,tax:0,cess:0,total:0,stockBase:0};const price=Number(it.unit_price??p.default_unit_price??0),lines=state.cart.map(item=>{const product=state.products.find(x=>x.id===item.product_id);return roundCurrency(Number(item.unit_price??product?.default_unit_price??0)*Number(item.qty||0))}),gross=roundCurrency(price*Number(it.qty||0)),index=state.cart.indexOf(it),disc=billDiscountShares(activeBillDiscount(),lines)[index]||0,taxable=roundCurrency(gross-disc);return {p,price,gross,disc,taxable,tax:0,cess:0,total:taxable,stockBase:Number(it.qty||0)}}
function setBillDiscount(value){state.billDiscount=Math.min(cartSubtotal(),Math.max(0,roundCurrency(value)));renderCart()}
function applyBillDiscount(rate){state.billDiscount=roundCurrency(cartSubtotal()*Number(rate)/100);renderCart()}
function discountRenderCart(){const c=$('#cart'),s=$('#summary');if(!c||!s)return;if(!state.cart.length)c.innerHTML='<div class="muted small">No products selected.</div>';else c.innerHTML=`<div class="cart-grid"><div class="cart-header"><span>Product</span><span>Qty</span><span>Unit</span><span>Price</span><span>Amount</span><span></span></div>${state.cart.map((it,i)=>{const l=discountCalcLine(it);return `<div class="cart-row"><div class="cart-product"><strong>${esc(l.p.name)}</strong><div class="small muted">${esc(l.p.sku)} • Available ${num(l.p.current_stock_base)} • Discount ${money(l.disc)}</div></div><div class="cart-field cart-quantity"><span class="cart-field-label">Qty</span><input class="input" aria-label="Quantity" type="number" min="0.01" step="0.01" value="${it.qty}" onchange="state.cart[${i}].qty=+this.value;renderCart()"></div><div class="cart-field cart-unit"><span class="cart-field-label">Unit</span><span class="cart-field-value">${esc(l.p.unit)}</span></div><div class="cart-field cart-price"><span class="cart-field-label">Price</span><input class="input" aria-label="Unit price" type="number" min="0" step="0.01" value="${l.price}" onchange="state.cart[${i}].unit_price=+this.value;renderCart()"></div><div class="cart-line-total"><span class="cart-field-label">Amount</span><strong class="right">${money(l.total)}</strong></div><button class="button cart-remove" aria-label="Remove ${esc(l.p.name)}" onclick="state.cart.splice(${i},1);renderCart()">×</button></div>`}).join('')}</div>`;const subtotal=cartSubtotal(),discount=activeBillDiscount(),total=roundCurrency(subtotal-discount);s.innerHTML=`<div class="between"><span>Total before discount</span><strong>${money(subtotal)}</strong></div><div class="row wrap" style="margin:10px 0"><button class="button" onclick="applyBillDiscount(5)">5%</button><button class="button" onclick="applyBillDiscount(10)">10%</button><button class="button" onclick="applyBillDiscount(15)">15%</button><button class="button" onclick="setBillDiscount(0)">Clear</button></div><label>Discount amount<input class="input" aria-label="Discount amount" type="number" min="0" max="${subtotal}" step="0.01" value="${discount}" onchange="setBillDiscount(this.value)"></label><div class="between"><span>Discount</span><strong>${money(discount)}</strong></div><hr><div class="between"><span>Total after discount</span><strong style="font-size:24px">${money(total)}</strong></div>`}
function validatedBilling(){masterBilling();const phone=$('#billCustomerPhone');if(phone){phone.type='tel';phone.inputMode='numeric';phone.maxLength=10;phone.pattern='[0-9]{10}';phone.title='Enter exactly 10 digits';phone.oninput=()=>{phone.value=phone.value.replace(/\D/g,'').slice(0,10);state.customerPhone=phone.value}}}
function productSearchById(query){const box=$('#searchResults');if(!box)return;const q=String(query||'').trim().toLowerCase();if(!q){box.classList.add('hide');return}const matches=sortProductsById(state.products.filter(p=>String(p.sku||'').toLowerCase().includes(q)||String(p.name||'').toLowerCase().includes(q))).slice(0,12);box.innerHTML=matches.map(p=>`<div class="product-result" onclick="addItem(${p.id})"><div><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.sku)} • Stock ${num(p.current_stock_base)}</div></div><div class="right">${money(p.default_unit_price)}<div class="small muted">per ${esc(p.unit)}</div></div></div>`).join('')||'<div class="small muted">No product found</div>';box.classList.remove('hide')}
async function sortedProductPage(){const q=state.productQuery||'',rows=sortProductsById(q?await api('/api/products?q='+encodeURIComponent(q)):state.products);$('#app').innerHTML=shell('Products',`<div class="row wrap"><input class="input" id="productQuery" placeholder="Search products" value="${esc(q)}" oninput="state.productQuery=this.value;products()"><button class="button primary" onclick="addProduct()">+ Product</button><button class="button" onclick="importMaster()">Upload Product Master</button></div><br><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Product ID</th><th>Product</th><th>Category</th><th>Unit</th><th>Default Unit Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.sku)}</td><td><strong>${esc(p.name)}</strong></td><td>${esc(p.category||'')}</td><td>${esc(p.unit)}</td><td>${money(p.default_unit_price)}</td><td>${num(p.current_stock_base)}</td><td>${esc(p.status)}</td><td><button class="button" onclick="productDetail(${p.id})">View</button></td></tr>`).join('')}</tbody></table></div></div>`)}
function sortedInventoryPage(){state.products=sortProductsById(state.products);return detailedInventory()}
function sortedPricingPage(){state.products=sortProductsById(state.products);return masterPricing()}
async function masterAddExpense(){openGeneric(`<div class="modalbox"><div class="between"><h3>Add Expense</h3><button class="button" onclick="closeModal()">×</button></div><form id="expenseForm"><div class="formgrid"><label>Date<input class="input" name="expense_date" type="date" value="${dateISO()}" required></label><label>Category<input class="input" name="category" value="Miscellaneous" required></label><label>Amount<input class="input" name="amount" type="number" min="0.01" step="0.01" value="0" required></label><label>Payment Mode<input class="input" name="payment_mode" value="Cash"></label><label>Vendor/Paid To<input class="input" name="vendor"></label><label>Recurring<select class="select" name="recurring"><option value="true">True</option><option value="false" selected>False</option></select></label><label class="full">Notes<textarea class="textarea" name="notes"></textarea></label></div><br><div class="row" style="justify-content:flex-end"><button type="button" class="button" onclick="closeModal()">Cancel</button><button class="button primary">Save</button></div></form></div>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{await api('/api/expenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});closeModal();expenses();toast('Expense saved')}catch(err){toast(err.message)}}}
async function discountOpenPayment(){if(!state.cart.length)return toast('Add products first');const subtotal=cartSubtotal(),discount=activeBillDiscount(),payable=roundCurrency(subtotal-discount);$('#modal').innerHTML=`<div class="modalbox"><div class="between"><h3>Complete payment</h3><button class="button" onclick="closeModal()">×</button></div><div class="payment-totals"><div class="between"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="between"><span>Discount</span><strong>−${money(discount)}</strong></div><div class="between payment-due"><span>Amount due</span><strong>${money(payable)}</strong></div></div><div id="payRows"></div><button class="button" onclick="addPayRow()">+ Payment</button><br><br><label>Notes<textarea class="textarea" id="billNotes"></textarea></label><br><div class="row" style="justify-content:flex-end"><button class="button" onclick="closeModal()">Cancel</button><button class="button primary" onclick="finalizeSale(${payable})">Finalize Invoice</button></div></div>`;$('#modal').classList.add('show');addPayRow(payable,'Cash')}
async function discountFinalizeSale(total){const phone=(state.customerPhone||'').trim();if(phone&&!/^\d{10}$/.test(phone))return toast('Mobile number must be exactly 10 digits.');const billWindow=window.open('about:blank','_blank');try{const discount=activeBillDiscount(),payable=roundCurrency(cartSubtotal()-discount),pays=$$('.payamt').map((el,i)=>({amount:+el.value,mode:$$('.paymode')[i].value})).filter(x=>x.amount>0),sum=pays.reduce((a,x)=>a+x.amount,0);if(Math.abs(sum-payable)>0.01||Math.abs(total-payable)>0.01)throw new Error('Payment total must match the amount after discount.');const d=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:null,customer_name:(state.customerName||'').trim(),customer_phone:phone,items:state.cart,discount,payments:pays,notes:$('#billNotes').value})});if(billWindow)billWindow.location='/api/invoice-pdf/'+d.invoice_id;closeModal();state.cart=[];state.billDiscount=0;state.customerName='';state.customerPhone='';await loadBasics();toast(`Bill ${d.invoice_number} completed`);billing()}catch(err){if(billWindow)billWindow.close();toast(err.message)}}
function discountNewBill(){state.billDiscount=0;return masterNewBill()}
function addItemToTop(id){const p=state.products.find(x=>x.id===id);if(!p)return;const index=state.cart.findIndex(x=>x.product_id===id),item=index>=0?state.cart.splice(index,1)[0]:{product_id:id,qty:0,sell_unit:p.unit};item.qty+=1;state.cart.unshift(item);hideSearch();const search=$('#prodSearch');if(search)search.value='';renderCart();const quantity=$('#cart .cart-row input[type="number"]');if(quantity){quantity.focus();quantity.select();quantity.scrollIntoView({block:'nearest'})}}
function updateHoldBillButton(){const button=$('#holdCurrentBill');if(button)button.disabled=!(state.cart||[]).length}
function heldBillRenderCart(){discountRenderCart();$$('#cart .cart-row').forEach((row,index)=>{const quantity=row.querySelector('input[type="number"]');if(quantity)quantity.dataset.cartQty=String(index);const priceInput=row.querySelector('input[aria-label="Unit price"]');if(priceInput){const price=document.createElement('span');price.className='right';price.setAttribute('aria-label','Fixed unit price');price.textContent=money(discountCalcLine(state.cart[index]).price);priceInput.replaceWith(price)}});updateHoldBillButton()}
function heldBilling(){masterBilling();const button=$('#app button[onclick="newBill()"]');button?.insertAdjacentHTML('afterend','<button class="button" id="holdCurrentBill" onclick="holdCurrentBill()" disabled>Hold Bill</button><button class="button" onclick="showHeldBills()">Held Bills</button>');updateHoldBillButton()}
async function holdCurrentBill(){if(!state.cart.length)return toast('Add products before holding a bill.');try{await api('/api/held-bills',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_name:(state.customerName||'').trim()||'Walk-in Customer',customer_phone:(state.customerPhone||'').trim(),pricing_mode:'STANDARD',items:state.cart,discount:activeBillDiscount()})});state.cart=[];state.billDiscount=0;state.customerName='';state.customerPhone='';billing();toast('Bill held. Start another bill or resume it from Held Bills.')}catch(error){toast(error.message)}}
async function showHeldBills(){try{const bills=await api('/api/held-bills');$('#modal').innerHTML=`<div class="modalbox"><div class="between"><h3>Held Bills</h3><button class="button" onclick="closeModal()">×</button></div>${bills.length?bills.map(bill=>`<div class="between notice" style="margin-bottom:8px"><div><strong>${esc(bill.ref)}</strong><div class="small muted">${esc(bill.customer_name||'Walk-in Customer')} • ${bill.items?.length||0} items • ${money(bill.discount||0)} discount • ${new Date(bill.created_at).toLocaleString()}</div></div><div class="row"><button class="button primary" onclick="resumeHeldBill(${bill.id})">Resume</button><button class="button" onclick="deleteHeldBill(${bill.id})">Delete</button></div></div>`).join(''):'<div class="muted small">No held bills.</div>'}</div>`;$('#modal').classList.add('show')}catch(error){toast(error.message)}}
async function resumeHeldBill(id){try{const held=await api('/api/held-bills/resume/'+id,{method:'POST'});state.cart=(held.items||[]).map(item=>{const resumed={...item};delete resumed.unit_price;return resumed});state.billDiscount=Number(held.discount||0);state.customerName=held.bill.customer_name||'';state.customerPhone=held.customer_phone||'';state.selectedCustomer=state.customers.find(customer=>customer.id===held.bill.customer_id)||null;closeModal();billing();toast('Held bill resumed')}catch(error){toast(error.message)}}
async function deleteHeldBill(id){try{await api('/api/held-bills/delete/'+id,{method:'POST'});showHeldBills()}catch(error){toast(error.message)}}
const originalDiscountCalcLine=discountCalcLine;
function lockedPriceCalcLine(item){const product=state.products.find(x=>x.id===item.product_id);return product?{...originalDiscountCalcLine({...item,unit_price:product.default_unit_price}),price:Number(product.default_unit_price||0)}:originalDiscountCalcLine(item)}
function lockBillPrice(){cartSubtotal=()=>roundCurrency((state.cart||[]).reduce((sum,item)=>sum+Number(state.products.find(product=>product.id===item.product_id)?.default_unit_price||0)*Number(item.qty||0),0));discountCalcLine=lockedPriceCalcLine;masterCalcLine=lockedPriceCalcLine;calcLine=lockedPriceCalcLine}
function fixedCalcLine(it){const p=state.products.find(x=>x.id===it.product_id);const factorUnit=u=>{const upb=Number(p.units_per_box||1),upc=Number(p.units_per_carton||upb*(p.boxes_per_carton||1));if(String(u).toLowerCase()==='piece')return 1;if(String(u).toLowerCase()==='carton')return upc||1;if(String(u).toLowerCase()==='box'||String(u).toLowerCase()==='packet'||String(u).toLowerCase()===String(p.unit).toLowerCase())return upb||1;return upb||1};const base=Number((state.pricing==='WHOLESALE'?p.wholesale_selling_price:p.retail_selling_price)||p.price?.[state.pricing==='WHOLESALE'?'wholesale_price':'retail_price']||0);const f0=factorUnit(p.unit)||1;const f=factorUnit(it.sell_unit)||1;const price=base*f/f0;const gross=price*Number(it.qty||0);const disc=Number(it.discount||0);const taxable=Math.max(0,gross-disc);const tax=taxable*Number(p.gst_rate||0)/100;const cess=taxable*Number(p.cess_rate||0)/100;return {p,price,gross,disc,taxable,tax,cess,total:taxable+tax+cess,stockBase:Number(it.qty||0)*f}}
function fixedSearchProducts(q){const box=$('#searchResults');if(!box)return;if(!q){box.classList.add('hide');return}const arr=state.products.filter(p=>(p.name+' '+p.sku+' '+(p.barcode||'')+' '+(p.category||'')).toLowerCase().includes(q.toLowerCase())).slice(0,12);box.innerHTML=arr.map(p=>`<div class="product-result" onclick="addItem(${p.id})"><div><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.sku)} • ${esc(p.category||'')} • Stock ${num(p.current_stock_base)}</div></div><div class="right">${money(state.pricing==='WHOLESALE'?p.wholesale_selling_price:p.retail_selling_price)}<div class="small muted">${esc(state.pricing)} • ${esc(p.unit)}</div></div></div>`).join('')||'<div class="small muted">No product found</div>';box.classList.remove('hide')}
function fixedRenderCart(){const c=$('#cart'),s=$('#summary');if(!c||!s)return;if(!state.cart.length)c.innerHTML='<div class="muted small">No items yet. Search a product above.</div>';else c.innerHTML=state.cart.map((it,i)=>{const l=fixedCalcLine(it);return `<div class="cart-row"><div><strong>${esc(l.p.name)}</strong><div class="small muted">${esc(l.p.sku)} • stock ${num(l.p.current_stock_base)}</div></div><input class="input" type="number" min="0.01" step="0.01" value="${it.qty}" onchange="state.cart[${i}].qty=+this.value;renderCart()"><select class="select" onchange="state.cart[${i}].sell_unit=this.value;renderCart()">${unitOptions(l.p).replace(new RegExp('>'+esc(it.sell_unit)+'<'),' selected>'+esc(it.sell_unit)+'<')}</select><input class="input" type="number" min="0" step="0.01" value="${it.discount||0}" onchange="state.cart[${i}].discount=+this.value;renderCart()"><button class="button" onclick="state.cart.splice(${i},1);renderCart()">×</button></div>`}).join('');const subtotal=state.cart.reduce((a,it)=>a+fixedCalcLine(it).gross,0),discount=state.cart.reduce((a,it)=>a+fixedCalcLine(it).disc,0),tax=state.cart.reduce((a,it)=>a+fixedCalcLine(it).tax,0),cess=state.cart.reduce((a,it)=>a+fixedCalcLine(it).cess,0),total=state.cart.reduce((a,it)=>a+fixedCalcLine(it).total,0);s.innerHTML=`<div class="between"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="between"><span>Discount</span><strong>${money(discount)}</strong></div><div class="between"><span>GST</span><strong>${money(tax)}</strong></div><div class="between"><span>Cess</span><strong>${money(cess)}</strong></div><hr><div class="between"><span>Total</span><strong style="font-size:24px">${money(total)}</strong></div>`}
function fixedBilling(){ensureToast();state.cart||=[];$('#app').innerHTML=shell('Fast Billing',`<div class="row wrap" style="margin-bottom:12px"><button class="button primary" onclick="newBill()">New Bill</button><div class="pill-nav">${['RETAIL','WHOLESALE'].map(x=>`<button class="${state.pricing===x?'active':''}" onclick="state.pricing='${x}';billing()">${x}</button>`).join('')}</div></div><div class="bill-layout"><div><div class="card"><div class="formgrid"><label>Customer name (optional)<input class="input" id="billCustomerName" value="${esc(state.customerName||'')}" oninput="state.customerName=this.value"></label><label>Mobile (optional)<input class="input" id="billCustomerPhone" value="${esc(state.customerPhone||'')}" oninput="state.customerPhone=this.value"></label><label>Product search<div class="searchbox"><input class="input" id="prodSearch" placeholder="Name / SKU / barcode" oninput="searchProducts(this.value)"><div id="searchResults" class="search-results hide"></div></div></label></div></div><br><div class="card"><h3>Cart</h3><div id="cart"></div></div></div><div><div class="card"><h3>Bill summary</h3><div id="summary"></div><br><button class="button primary" style="width:100%" onclick="openPayment()">Payment & Complete</button></div></div></div><div id="modal" class="modal"></div>`);renderCart()}
