function fixedAddPayRow(amount=0,mode='Cash'){const d=document.createElement('div');d.className='formgrid';d.style.marginBottom='8px';d.innerHTML=`<label>Mode<select class="select paymode"><option ${mode==='Cash'?'selected':''}>Cash</option><option ${mode==='UPI'?'selected':''}>UPI</option><option ${mode==='Card'?'selected':''}>Card</option><option ${mode==='Credit'?'selected':''}>Credit</option><option ${mode==='Other'?'selected':''}>Other</option></select></label><label>Amount<input class="input payamt" type="number" min="0" step="0.01" value="${amount}"></label>`;$('#payRows').appendChild(d)}
async function fixedFinalizeSale(total){const billWindow=window.open('about:blank','_blank');try{const pays=$$('.payamt').map((el,i)=>({amount:+el.value,mode:$$('.paymode')[i].value})).filter(x=>x.amount>0);const sum=pays.reduce((a,x)=>a+x.amount,0);if(Math.abs(sum-total)>0.01)throw new Error('Full payment is required.');const d=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:null,customer_name:(state.customerName||'').trim(),customer_phone:(state.customerPhone||'').trim(),pricing_mode:state.pricing,items:state.cart,payments:pays,notes:$('#billNotes').value})});if(billWindow)billWindow.location='/api/invoice-pdf/'+d.invoice_id;closeModal();state.cart=[];state.customerName='';state.customerPhone='';await loadBasics();toast(`Bill ${d.invoice_number} completed and saved to Sales`);billing()}catch(e){if(billWindow)billWindow.close();toast(e.message)}}
function fixedHoldBill(){if(!state.cart.length)return toast('Nothing to hold');api('/api/held-bills',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:null,customer_name:(state.customerName||'').trim()||'Walk-in Customer',pricing_mode:'WHOLESALE',items:state.cart})}).then(()=>{state.cart=[];toast('Bill held');billing()}).catch(e=>toast(e.message))}
