function fixedAddProduct(){modalForm('New Product',[{k:'sku',l:'Product Code / SKU'},{k:'name',l:'Product Name'},{k:'category',l:'Category'},{k:'subcategory',l:'Subcategory'},{k:'unit',l:'Unit',v:'Box'},{k:'units_per_box',l:'Units per Box',v:1},{k:'boxes_per_carton',l:'Boxes per Carton',v:1},{k:'units_per_carton',l:'Units per Carton',v:1},{k:'cost_price',l:'Cost Price',v:0},{k:'mrp',l:'MRP',v:0},{k:'retail_price',l:'Retail Selling Price',v:0},{k:'wholesale_price',l:'Wholesale Selling Price',v:0},{k:'gst_rate',l:'GST Rate',v:0},{k:'cess_rate',l:'Compensation Cess Rate',v:0},{k:'hsn',l:'HSN Code',v:'3604'},{k:'opening_stock',l:'Opening Stock',v:0},{k:'reorder_level',l:'Minimum Stock / Reorder Level',v:0},{k:'brand',l:'Brand / Manufacturer'},{k:'batch',l:'Batch/Lot'},{k:'status',l:'Product Status',v:'ACTIVE'}],async vals=>{await api('/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(vals)});await loadBasics();closeModal();products()})}
async function fixedProductDetail(pid){const d=await api('/api/products/'+pid);const p=d.product;openGeneric(`<div class="modalbox"><div class="between"><h3>${esc(p.name)}</h3><button class="button" onclick="closeModal()">×</button></div><div class="grid two"><div class="notice">Product Code / SKU <strong>${esc(p.sku)}</strong></div><div class="notice">Stock <strong>${num(d.stock)}</strong> base units</div><div class="notice">Category <strong>${esc(p.category||'')}</strong></div><div class="notice">Status <strong>${esc(p.status)}</strong></div></div><br><div class="card"><h3>Material Master Details</h3><div class="table-wrap"><table class="table"><tr><th>Unit</th><th>Box</th><th>Carton</th><th>Reorder</th><th>HSN</th><th>GST</th><th>Cess</th></tr><tr><td>${esc(p.unit)}</td><td>${num(p.units_per_box)}</td><td>${num(p.units_per_carton)}</td><td>${num(p.reorder_level)}</td><td>${esc(p.hsn||'')}</td><td>${num(p.gst_rate)}%</td><td>${num(p.cess_rate)}%</td></tr></table></div></div><br><div class="card"><h3>Current Pricing</h3><div class="table-wrap"><table class="table"><tr><th>Cost</th><th>MRP</th><th>Retail Selling</th><th>Wholesale Selling</th></tr><tr><td>${money(p.cost_price)}</td><td>${money(p.mrp)}</td><td>${money(p.retail_selling_price)}</td><td>${money(p.wholesale_selling_price)}</td></tr></table></div></div><br><div class="row"><button class="button" onclick="removeStockForm(${pid},'${esc(p.unit)}')">Remove Stock</button><button class="button" onclick="inventoryLedger(${pid})">Stock Ledger</button><button class="button danger" onclick="removeProduct(${pid})">Remove Product</button></div></div>`)}
async function removeProduct(pid){if(!confirm('Remove this product from the active material master? Products used in transactions will be archived instead.'))return;try{const d=await api('/api/products/'+pid+'/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await loadBasics();closeModal();products();toast(d.action==='product removed'?'Product removed':'Product archived as inactive')}catch(e){toast(e.message)}}
