async function fixedAnalytics(){const d=await api('/api/analytics?preset=today');const k=d.kpi;$('#app').innerHTML=shell('Sales Analytics',`<div class="grid kpis"><div class="card kpi"><div class="label">Total Sales</div><div class="value">${money(k.sales)}</div></div><div class="card kpi"><div class="label">Bills</div><div class="value">${k.bills}</div></div><div class="card kpi"><div class="label">Avg Bill</div><div class="value">${money(k.avg_bill)}</div></div><div class="card kpi"><div class="label">Gross Profit</div><div class="value">${money(k.gross_profit)}</div></div></div><br><div class="grid two"><div class="card"><h3>Top Products</h3><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Revenue</th><th>Qty</th></tr>${d.top_products.slice(0,10).map(x=>`<tr><td>${esc(x.name)}</td><td>${money(x.revenue)}</td><td>${num(x.qty)}</td></tr>`).join('')}</table></div></div><div class="card"><h3>Payment analytics</h3>${d.payments.map(x=>`<div class="between notice"><span>${esc(x.mode)}</span><strong>${money(x.amount)}</strong></div>`).join('')}</div></div>`)}
