function fixedNav(){const admin=state.user?.role==='OWNER';const routes=[['dashboard','Dashboard'],['billing','Billing'],...(admin?[['sales','Sales'],['products','Products'],['inventory','Inventory'],['customers','Customers']]:[]),['expenses','Expenses'],...(admin?[['pricing','Pricing']]:[]),['analytics','Analytics'],...(admin?[['settings','Settings'],['users','Users']]:[]),['backup','Backup & Export']];return `<aside class="sidebar"><div class="brand">🎇 Fireworks CRM<small>${admin?'Administrator':'Staff'} access</small></div><button class="button sidebar-close" aria-label="Close navigation" onclick="closeMenu()">×</button><div class="nav">${routes.map(([r,t])=>`<button class="${state.route===r?'active':''}" onclick="go('${r}')">${t}</button>`).join('')}</div></aside>`}
async function usersPage(){if(state.user?.role!=='OWNER'){go('dashboard');return}try{const users=await api('/api/users');$('#app').innerHTML=shell('User Management',`<div class="grid two"><div class="card"><h3>Create staff account</h3><form id="newStaffForm"><div class="formgrid"><label>Username<input class="input" name="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,31}" autocomplete="off" required></label><label>Temporary password<input class="input" name="password" type="password" minlength="8" autocomplete="new-password" required></label></div><p class="small muted">Staff accounts can use Dashboard, Billing, Expenses, Analytics, and Backup &amp; Export.</p><button class="button primary">Create staff account</button></form></div><div class="card"><h3>Access roles</h3><p class="small muted">Administrators retain full access. Staff can record bills and expenses, review dashboard and analytics, and download exports or backups. Staff cannot manage products, customers, pricing, business settings, or users.</p></div></div><br><div class="card"><h3>Accounts</h3><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${users.map(user=>`<tr><td><strong>${esc(user.username)}</strong></td><td>${user.role==='OWNER'?'Administrator':'Staff'}</td><td><span class="tag ${user.active?'good':'bad'}">${user.active?'Active':'Inactive'}</span></td><td>${esc(String(user.created_at||'').slice(0,10))}</td><td>${user.id===state.user.id?'<span class="small muted">Current account</span>':`<button class="button ${user.active?'danger':'primary'}" onclick="setStaffStatus(${user.id},${user.active?0:1})">${user.active?'Deactivate':'Activate'}</button>`}</td></tr>`).join('')}</tbody></table></div></div>`);$('#newStaffForm').onsubmit=createStaffAccount}catch(error){$('#app').innerHTML=shell('User Management',`<div class="notice bad">${esc(error.message)}</div>`)}}
async function createStaffAccount(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));try{await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});toast('Staff account created');usersPage()}catch(error){toast(error.message)}}
async function setStaffStatus(id,active){try{await api(`/api/users/${id}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!!active})});toast(active?'Account activated':'Account deactivated');usersPage()}catch(error){toast(error.message)}}
async function fixedExpenses(){const d=await api('/api/expenses?start='+new Date(new Date().getFullYear(),0,1).toISOString().slice(0,10)+'&end='+dateISO());const total=d.reduce((a,x)=>a+x.amount,0);const byDay={};d.forEach(x=>byDay[x.expense_date]=(byDay[x.expense_date]||0)+Number(x.amount||0));const days=Object.entries(byDay).sort((a,b)=>a[0].localeCompare(b[0]));const max=Math.max(...days.map(x=>x[1]),1);$('#app').innerHTML=shell('Expenses',`<div class="grid kpis"><div class="card kpi"><div class="label">YTD Expenses</div><div class="value">${money(total)}</div></div><div class="card kpi"><div class="label">Entries</div><div class="value">${d.length}</div></div></div><br><div class="row"><button class="button primary" onclick="addExpense()">+ Add Expense</button><button class="button" onclick="addRecurringExpense()">+ Recurring</button></div><br><div class="card"><h3>Day-wise Expenses</h3><div class="chart">${days.length?days.map(([day,value])=>`<div class="bar" style="height:${Math.max(8,value/max*88)}%" title="${day}: ${money(value)}"><b>${money(value)}</b><span>${day.slice(5)}</span></div>`).join(''):'<div class="muted small">No expenses recorded.</div>'}</div></div><br><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Category</th><th>Vendor</th><th>Mode</th><th>Amount</th></tr></thead><tbody>${d.map(x=>`<tr><td>${x.expense_date}</td><td>${esc(x.category)}</td><td>${esc(x.vendor||'')}</td><td>${x.payment_mode}</td><td>${money(x.amount)}</td></tr>`).join('')}</tbody></table></div></div>`)}
function fixedRecurringExpense(){modalForm('Recurring Expense',[],async vals=>{await api('/api/recurring-expenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(vals)});closeModal();toast('Recurring expense saved');fixedExpenses()},[['category','Category','Miscellaneous'],['amount','Amount',0],['payment_mode','Payment Mode','Cash'],['vendor','Vendor/Paid To'],['frequency','Frequency','Monthly'],['start_date','Start Date',dateISO()],['end_date','End Date'],['notes','Notes']])}
function fixedSettings(){const s=state.settings,t=state.targets;$('#app').innerHTML=shell('Settings',`<div class="card"><h3>Business & Invoice Settings</h3><form onsubmit="saveSettings(event)"><div class="formgrid"><label>Business Name<input class="input" id="bs_name" value="${esc(s.business_name)}"></label><label>License Number<input class="input" id="bs_license" value="${esc(s.license_number||'')}"></label><label>Phone<input class="input" id="bs_phone" value="${esc(s.phone||'')}"></label><label>Email<input class="input" id="bs_email" value="${esc(s.email||'')}"></label><label class="full">Address<textarea class="textarea" id="bs_address">${esc(s.address)}</textarea></label><label>Invoice Prefix<input class="input" id="bs_prefix" value="${esc(s.invoice_prefix)}"></label><label>Daily Sales Target<input class="input" id="tg_daily" type="number" value="${t.daily}"></label><label>Weekly Sales Target<input class="input" id="tg_weekly" type="number" value="${t.weekly}"></label><label>Monthly Sales Target<input class="input" id="tg_monthly" type="number" value="${t.monthly}"></label><label>Seasonal Sales Target<input class="input" id="tg_seasonal" type="number" value="${t.seasonal}"></label><label>Season Start<input class="input" id="tg_ss" type="date" value="${t.season_start||''}"></label><label>Season End<input class="input" id="tg_se" type="date" value="${t.season_end||''}"></label></div><br><button class="button primary">Save Settings</button></form></div>`)}
async function fixedSaveSettings(e){e.preventDefault();const s={...state.settings,gstin:'',default_gst_rate:0,default_cess_rate:0,business_name:$('#bs_name').value,license_number:$('#bs_license').value,phone:$('#bs_phone').value,email:$('#bs_email').value,address:$('#bs_address').value,invoice_prefix:$('#bs_prefix').value};const t={...state.targets,daily:+$('#tg_daily').value,weekly:+$('#tg_weekly').value,monthly:+$('#tg_monthly').value,seasonal:+$('#tg_seasonal').value,season_start:$('#tg_ss').value,season_end:$('#tg_se').value};await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({settings:s,targets:t})});await loadBasics();toast('Settings saved')}
function masterCalcLine(it){const p=state.products.find(x=>x.id===it.product_id);const price=Number(it.unit_price??p.default_unit_price??0);const qty=Number(it.qty||0);return {p,price,gross:qty*price,disc:0,taxable:qty*price,tax:0,cess:0,total:qty*price,stockBase:qty}}
function masterRenderCart(){const c=$('#cart'),s=$('#summary');if(!c||!s)return;if(!state.cart.length)c.innerHTML='<div class="muted small">No products selected.</div>';else c.innerHTML=state.cart.map((it,i)=>{const l=masterCalcLine(it);return `<div class="cart-row"><div><strong>${esc(l.p.name)}</strong><div class="small muted">${esc(l.p.sku)} • Available ${num(l.p.current_stock_base)} • Default ${money(l.p.default_unit_price)}</div></div><input class="input" type="number" min="0.01" step="0.01" value="${it.qty}" onchange="state.cart[${i}].qty=+this.value;renderCart()"><input class="input" type="number" min="0" step="0.01" value="${l.price}" aria-label="Selling unit price" onchange="state.cart[${i}].unit_price=+this.value;renderCart()"><span class="right"><strong>${money(l.total)}</strong></span><button class="button" onclick="state.cart.splice(${i},1);renderCart()">×</button></div>`}).join('');const total=state.cart.reduce((a,it)=>a+masterCalcLine(it).total,0);s.innerHTML=`<div class="between"><span>Total</span><strong style="font-size:24px">${money(total)}</strong></div>`}
function masterSearchProducts(q){const box=$('#searchResults');if(!box)return;if(!q){box.classList.add('hide');return}const arr=state.products.filter(p=>(p.name+' '+p.sku+' '+(p.category||'')+' '+(p.subcategory||'')).toLowerCase().includes(q.toLowerCase())).slice(0,12);box.innerHTML=arr.map(p=>`<div class="product-result" onclick="addItem(${p.id})"><div><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.sku)} • Stock ${num(p.current_stock_base)}</div></div><div class="right">${money(p.default_unit_price)}<div class="small muted">per ${esc(p.unit)}</div></div></div>`).join('')||'<div class="small muted">No product found</div>';box.classList.remove('hide')}
function masterBilling(){ensureToast();state.cart||=[];$('#app').innerHTML=shell('Billing',`<div class="row wrap billing-actions" style="margin-bottom:12px"><button class="button primary" onclick="newBill()">New Bill</button></div><div class="bill-layout"><div><div class="card"><div class="formgrid"><label>Customer name (optional)<input class="input" id="billCustomerName" value="${esc(state.customerName||'')}" oninput="state.customerName=this.value"></label><label>Mobile (optional)<input class="input" id="billCustomerPhone" value="${esc(state.customerPhone||'')}" oninput="state.customerPhone=this.value"></label><label>Product search<div class="searchbox"><input class="input" id="prodSearch" placeholder="Name / Product ID / category" oninput="searchProducts(this.value)"><div id="searchResults" class="search-results hide"></div></div></label></div></div><br><div class="card"><h3>Items</h3><div class="small muted" style="margin-bottom:8px">Quantity × Selling Unit Price</div><div id="cart"></div></div></div><div><div class="card bill-summary-card"><h3>Bill total</h3><div id="summary"></div><br><button class="button primary bill-payment-button" style="width:100%" onclick="openPayment()">Payment &amp; Complete</button></div></div></div><div id="modal" class="modal"></div>`);renderCart()}
function masterNewBill(){state.cart=[];state.selectedCustomer=null;state.customerName='';state.customerPhone='';billing()}
async function masterFinalizeSale(total){const billWindow=window.open('about:blank','_blank');try{const pays=$$('.payamt').map((el,i)=>({amount:+el.value,mode:$$('.paymode')[i].value})).filter(x=>x.amount>0);const sum=pays.reduce((a,x)=>a+x.amount,0);if(Math.abs(sum-total)>0.01)throw new Error('Full payment is required.');const d=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:null,customer_name:(state.customerName||'').trim(),customer_phone:(state.customerPhone||'').trim(),items:state.cart,payments:pays,notes:$('#billNotes').value})});if(billWindow)billWindow.location='/api/invoice-pdf/'+d.invoice_id;closeModal();state.cart=[];await loadBasics();toast(`Bill ${d.invoice_number} completed`);billing()}catch(e){if(billWindow)billWindow.close();toast(e.message)}}
async function masterProducts(){const q=state.productQuery||'';const rows=q?await api('/api/products?q='+encodeURIComponent(q)):state.products;$('#app').innerHTML=shell('Products',`<div class="row wrap"><input class="input" id="productQuery" placeholder="Search products" value="${esc(q)}" oninput="state.productQuery=this.value;products()"><button class="button primary" onclick="addProduct()">+ Product</button><button class="button" onclick="importMaster()">Upload Product Master</button></div><br><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Product ID</th><th>Product</th><th>Category</th><th>Unit</th><th>Default Unit Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.sku)}</td><td><strong>${esc(p.name)}</strong></td><td>${esc(p.category||'')}</td><td>${esc(p.unit)}</td><td>${money(p.default_unit_price)}</td><td>${num(p.current_stock_base)}</td><td>${esc(p.status)}</td><td><button class="button" onclick="productDetail(${p.id})">View</button></td></tr>`).join('')}</tbody></table></div></div>`)}
function masterAddProduct(){modalForm('New Product',[{k:'sku',l:'Product ID / Serial Number'},{k:'name',l:'Product Name'},{k:'category',l:'Category'},{k:'subcategory',l:'Subcategory'},{k:'brand',l:'Brand / Manufacturer'},{k:'unit',l:'Unit',v:'unit'},{k:'unit_price',l:'Default Unit Selling Price',v:0},{k:'opening_stock',l:'Opening Stock',v:0},{k:'reorder_level',l:'Minimum Stock',v:0},{k:'status',l:'Product Status',v:'ACTIVE'}],async vals=>{await api('/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(vals)});await loadBasics();closeModal();products()})}
async function masterProductDetail(pid){const d=await api('/api/products/'+pid),p=d.product;openGeneric(`<div class="modalbox"><div class="between"><h3>${esc(p.name)}</h3><button class="button" onclick="closeModal()">×</button></div><div class="grid two"><div class="notice">Product ID <strong>${esc(p.sku)}</strong></div><div class="notice">Available Stock <strong>${num(d.stock)} ${esc(p.unit)}</strong></div><div class="notice">Default Unit Price <strong>${money(p.default_unit_price)}</strong></div><div class="notice">Status <strong>${esc(p.status)}</strong></div></div><br><div class="row"><button class="button" onclick="removeStockForm(${pid},'${esc(p.unit)}')">Remove Stock</button><button class="button" onclick="inventoryLedger(${pid})">Stock Ledger</button><button class="button danger" onclick="removeProduct(${pid})">Remove Product</button></div></div>`)}
function masterPricing(){const ps=state.products;$('#app').innerHTML=shell('Product Prices',`<div class="row"><button class="button primary" onclick="pricingOne()">Change Default Unit Price</button></div><br><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Product ID</th><th>Product</th><th>Default Unit Price</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${money(p.default_unit_price)}</td></tr>`).join('')}</tbody></table></div></div>`)}
function masterPricingOne(){modalForm('Change Default Unit Price',[],async vals=>{await api('/api/pricing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:+vals.product_id,unit_price:+vals.unit_price})});await loadBasics();closeModal();pricing();toast('Default unit price saved')},[['product_id','Product ID'],['unit_price','Default Unit Selling Price',0]])}
async function masterSales(){const d=await api('/api/invoices?start=1900-01-01&end='+dateISO());$('#app').innerHTML=shell('Sales',`<div class="card"><div class="between"><h3>Invoices</h3><button class="button primary" onclick="go('billing');newBill()">+ New Bill</button></div><br><div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Total</th><th>Received</th><th>Actions</th></tr></thead><tbody>${d.map(x=>`<tr><td><strong>${esc(x.invoice_number)}</strong></td><td>${x.invoice_date}</td><td>${esc(x.customer_name_snapshot)}</td><td>${money(x.grand_total)}</td><td>${money(x.amount_received)}</td><td><button class="button" onclick="window.open('/api/invoice-pdf/${x.id}','_blank')">PDF</button><button class="button" onclick="returnInvoice(${x.id})">Return</button></td></tr>`).join('')}</tbody></table></div></div><div id="modal" class="modal"></div>`)}
function masterCustomers(){$('#app').innerHTML=shell('Customers',`<div class="row"><button class="button primary" onclick="addCustomer()">+ Customer</button></div><br><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Address</th><th>Notes</th></tr></thead><tbody>${state.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="small muted">${esc(c.customer_code)}</div></td><td>${esc(c.phone||'')}</td><td>${esc(c.address||'')}</td><td>${esc(c.notes||'')}</td></tr>`).join('')}</tbody></table></div></div>`)}
async function masterInventory(){const products=state.products;$('#app').innerHTML=shell('Inventory',`<div class="row wrap"><button class="button primary" onclick="adjustStockForm()">Stock Adjustment</button></div><br><div class="grid kpis"><div class="card kpi"><div class="label">Total Products</div><div class="value">${products.length}</div></div><div class="card kpi"><div class="label">Low Stock</div><div class="value">${products.filter(p=>p.current_stock_base<=p.reorder_level).length}</div></div><div class="card kpi"><div class="label">Out of Stock</div><div class="value">${products.filter(p=>p.current_stock_base<=0).length}</div></div></div><br><div class="card"><h3>Current Stock</h3><div class="table-wrap"><table class="table"><thead><tr><th>Product ID</th><th>Product</th><th>Unit</th><th>Available</th><th>Minimum</th><th>Default Price</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${esc(p.unit)}</td><td>${num(p.current_stock_base)}</td><td>${num(p.reorder_level)}</td><td>${money(p.default_unit_price)}</td><td><button class="button" onclick="productDetail(${p.id})">View</button></td></tr>`).join('')}</tbody></table></div></div>`)}
function masterImport(){openGeneric(`<div class="modalbox"><div class="between"><h3>Product Master Upload</h3><button class="button" onclick="closeModal()">×</button></div><p class="small muted">Upload the one-time Excel master. Existing Product IDs are rejected as duplicates.</p><input class="input" type="file" id="masterFile" accept=".xlsx,.csv"><br><br><button class="button primary" onclick="masterPreview()">Validate & Preview</button></div>`)}
async function masterPreview(){const f=$('#masterFile').files[0];if(!f)return toast('Choose the Product Master file');const fd=new FormData();fd.append('file',f);fd.append('mode','preview');const d=await api('/api/import/products',{method:'POST',body:fd}).catch(e=>({error:e.message}));if(d.error)return toast(d.error);window.__masterFile=f;const fields=[['sku','Product ID / Serial Number'],['name','Product Name'],['category','Category'],['subcategory','Subcategory'],['brand','Brand / Manufacturer'],['unit','Unit'],['unit_price','Default Unit Selling Price'],['opening_stock','Opening Stock'],['reorder_level','Minimum Stock'],['status','Product Status']];openGeneric(`<div class="modalbox"><div class="between"><h3>Preview & Mapping</h3><button class="button" onclick="closeModal()">×</button></div><div class="notice">Total rows: ${d.count}. Preview errors: ${d.errors?.length||0}</div><br><div class="formgrid">${fields.map(([k,l])=>`<label>${l}<select class="select mapfield" data-key="${k}"><option value="">Not mapped</option>${d.headers.map(h=>`<option value="${esc(h)}" ${d.mapping?.[k]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div><br><button class="button primary" onclick="masterConfirm()">Confirm Import</button></div>`)}
async function masterConfirm(){const mapping={};$$('.mapfield').forEach(x=>mapping[x.dataset.key]=x.value||null);if(!mapping.sku||!mapping.name||!mapping.unit_price)return toast('Product ID, Product Name, and Unit Price are mandatory');const fd=new FormData();fd.append('file',window.__masterFile);fd.append('mapping',JSON.stringify(mapping));try{const d=await api('/api/import/products',{method:'POST',body:fd});await loadBasics();closeModal();toast(`Imported ${d.imported} of ${d.total_rows} products`);products()}catch(e){if(e.validation_errors){openGeneric(`<div class="modalbox"><div class="between"><h3>Product Master Import Errors</h3><button class="button" onclick="closeModal()">×</button></div><div class="notice bad">Total rows: ${e.total_rows} • Failed: ${e.failed_rows} • Duplicates: ${e.duplicate_rows}</div><br><div class="table-wrap"><table class="table"><tr><th>Row</th><th>Error</th></tr>${e.validation_errors.map(x=>`<tr><td>${x.row}</td><td>${esc(x.error)}</td></tr>`).join('')}</table></div></div>`)}else toast(e.message)}}
function detailedRenderCart(){const c=$('#cart'),s=$('#summary');if(!c||!s)return;if(!state.cart.length)c.innerHTML='<div class="muted small">No products selected.</div>';else c.innerHTML=`<div class="cart-grid"><div class="cart-header"><span>Product</span><span>Qty</span><span>Unit</span><span>Price</span><span>Amount</span><span></span></div>${state.cart.map((it,i)=>{const l=masterCalcLine(it);return `<div class="cart-row"><div><strong>${esc(l.p.name)}</strong><div class="small muted">${esc(l.p.sku)} • Available ${num(l.p.current_stock_base)}</div></div><input class="input" aria-label="Quantity" type="number" min="0.01" step="0.01" value="${it.qty}" onchange="state.cart[${i}].qty=+this.value;renderCart()"><span>${esc(l.p.unit)}</span><input class="input" aria-label="Unit price" type="number" min="0" step="0.01" value="${l.price}" onchange="state.cart[${i}].unit_price=+this.value;renderCart()"><strong class="right">${money(l.total)}</strong><button class="button" aria-label="Remove ${esc(l.p.name)}" onclick="state.cart.splice(${i},1);renderCart()">×</button></div>`}).join('')}</div>`;const lines=state.cart.map(it=>{const l=masterCalcLine(it);return `<div class="between bill-summary-line"><span>${esc(l.p.name)} <span class="small muted">${num(it.qty)} ${esc(l.p.unit)} × ${money(l.price)}</span></span><strong>${money(l.total)}</strong></div>`}).join('');const total=state.cart.reduce((a,it)=>a+masterCalcLine(it).total,0);s.innerHTML=`${lines}<hr><div class="between"><span>Total</span><strong style="font-size:24px">${money(total)}</strong></div>`}
function masterPurchaseForm(){const products=state.products.filter(p=>p.status!=='INACTIVE');openGeneric(`<div class="modalbox"><div class="between"><h3>Add Stock / GRN</h3><button class="button" onclick="closeModal()">×</button></div><form id="purchaseForm"><div class="formgrid"><label>Product<select class="select" name="product_id" required onchange="this.form.sell_unit.value=state.products.find(p=>p.id===+this.value)?.unit||'unit'">${products.map(p=>`<option value="${p.id}">${esc(p.sku)} • ${esc(p.name)} (stock ${num(p.current_stock_base)})</option>`).join('')}</select></label><label>Quantity<input class="input" name="qty" type="number" min="0.01" step="0.01" value="1" required></label><label>Unit<input class="input" name="sell_unit" value="${esc(products[0]?.unit||'unit')}" required></label><label>Cost per unit<input class="input" name="cost_price" type="number" min="0" step="0.01" value="0"></label><label>Supplier<input class="input" name="supplier_name"></label><label>Purchase date<input class="input" name="purchase_date" type="date" value="${dateISO()}"></label><label>Supplier invoice no.<input class="input" name="invoice_number"></label><label>Batch / lot<input class="input" name="batch_number"></label><label>Location<input class="input" name="location"></label><label>Freight<input class="input" name="freight" type="number" min="0" step="0.01" value="0"></label></div><br><div class="row" style="justify-content:flex-end"><button type="button" class="button" onclick="closeModal()">Cancel</button><button class="button primary">Add Stock</button></div></form></div>`);$('#purchaseForm').onsubmit=async e=>{e.preventDefault();const vals=Object.fromEntries(new FormData(e.target));try{const p=products.find(x=>String(x.id)===vals.product_id);await api('/api/purchases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplier_name:vals.supplier_name,purchase_date:vals.purchase_date,invoice_number:vals.invoice_number,freight:+vals.freight||0,items:[{product_id:+vals.product_id,qty:+vals.qty,sell_unit:vals.sell_unit||p?.unit,cost_price:+vals.cost_price||0,batch_number:vals.batch_number,location:vals.location}]})});await loadBasics();closeModal();inventory();toast('Stock added')}catch(err){toast(err.message)}}}
async function detailedSales(){const d=await api('/api/invoices?start=1900-01-01&end='+dateISO());$('#app').innerHTML=shell('Sales',`<div class="card"><div class="between"><div><h3>Invoices</h3><div class="small muted">Delete voids the sale and restores stock; invoice and payment history are retained.</div></div><button class="button primary" onclick="go('billing');newBill()">+ New Bill</button></div><br><div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Total</th><th>Received</th><th>Actions</th></tr></thead><tbody>${d.map(x=>`<tr><td><strong>${esc(x.invoice_number)}</strong></td><td>${esc(x.invoice_date)}</td><td>${esc(x.customer_name_snapshot)}</td><td>${money(x.grand_total)}</td><td>${money(x.amount_received)}</td><td><div class="row"><button class="button" onclick="window.open('/api/invoice-pdf/${x.id}','_blank')">PDF</button><button class="button" onclick="returnInvoice(${x.id})">Return</button><button class="button danger" onclick="voidSale(${x.id},'${esc(x.invoice_number)}')">Delete</button></div></td></tr>`).join('')}</tbody></table></div></div><div id="modal" class="modal"></div>`)}
async function voidSale(id,invoice){if(!confirm(`Delete ${invoice}? This will void the sale and restore its stock. The invoice and payment audit history will be retained.`))return;try{await api(`/api/invoices/${id}/void`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await loadBasics();toast(`${invoice} voided and stock restored`);sales()}catch(e){toast(e.message)}}
async function detailedInventory(){const products=state.products;$('#app').innerHTML=shell('Inventory',`<div class="row wrap"><button class="button primary" onclick="purchaseForm()">+ Add Stock / GRN</button><button class="button" onclick="adjustStockForm()">Stock Adjustment</button></div><br><div class="grid kpis"><div class="card kpi"><div class="label">Total Products</div><div class="value">${products.length}</div></div><div class="card kpi"><div class="label">Low Stock</div><div class="value">${products.filter(p=>p.current_stock_base<=p.reorder_level).length}</div></div><div class="card kpi"><div class="label">Out of Stock</div><div class="value">${products.filter(p=>p.current_stock_base<=0).length}</div></div></div><br><div class="card"><h3>Current Stock</h3><div class="table-wrap"><table class="table"><thead><tr><th>Product ID</th><th>Product</th><th>Unit</th><th>Available</th><th>Minimum</th><th>Default Price</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${esc(p.unit)}</td><td>${num(p.current_stock_base)}</td><td>${num(p.reorder_level)}</td><td>${money(p.default_unit_price)}</td><td><button class="button" onclick="productDetail(${p.id})">View</button></td></tr>`).join('')}</tbody></table></div></div>`)}
function detailedBackup(){$('#app').innerHTML=shell('Backup & Export',`<div class="grid three"><div class="card"><h3>Full Backup</h3><p class="small muted">All core application tables as JSON.</p><a class="button primary" href="/api/backup">Download Backup</a></div><div class="card"><h3>Sales Reports</h3><p class="small muted">Invoice summary or line-by-line sales and payment detail.</p><a class="button" href="/api/export/sales.xlsx">Summary Excel</a><br><br><a class="button primary" href="/api/export/sales-detailed.xlsx">Detailed Sales Excel</a><br><br><a class="button" href="/api/export/sales.pdf">Export PDF</a></div><div class="card"><h3>Help</h3><p class="small muted">Initial Product Master → map/validate → import. Then use Billing, Inventory, Pricing and Expenses directly.</p></div></div><br><div class="notice warn">Keep backup files in a secure location. Financially important records are not hard-deleted.</div>`)}
function applyUiFixes(){nav=fixedNav;dashboard=fixedDashboard;billing=masterBilling;newBill=masterNewBill;searchProducts=masterSearchProducts;calcLine=masterCalcLine;renderCart=detailedRenderCart;addPayRow=fixedAddPayRow;finalizeSale=masterFinalizeSale;holdBill=()=>toast('Hold Bills are disabled');sales=detailedSales;products=masterProducts;inventory=detailedInventory;purchaseForm=masterPurchaseForm;backup=detailedBackup;expenses=fixedExpenses;addRecurringExpense=fixedRecurringExpense;addProduct=masterAddProduct;productDetail=masterProductDetail;importMaster=masterImport;previewMaster=masterPreview;confirmMasterImport=masterConfirm;customers=masterCustomers;addCustomer=fixedAddCustomer;pricing=masterPricing;pricingOne=masterPricingOne;pricingBulk=()=>toast('Bulk price tiers are not part of the Product Master');analytics=fixedAnalytics;settingsPage=fixedSettings;saveSettings=fixedSaveSettings;state.pricing='STANDARD';if(state.user)render()}
window.addEventListener('load',()=>setTimeout(applyUiFixes,100));
window.addEventListener('load',()=>setTimeout(()=>{toast=fixedToast;billing=heldBilling;newBill=discountNewBill;addItem=addItemToTop;holdBill=holdCurrentBill;showHeld=showHeldBills;resumeHeld=resumeHeldBill;deleteHeld=deleteHeldBill;searchProducts=productSearchById;lockBillPrice();renderCart=heldBillRenderCart;openPayment=discountOpenPayment;finalizeSale=discountFinalizeSale;products=sortedProductPage;inventory=sortedInventoryPage;pricing=sortedPricingPage;addExpense=masterAddExpense;state.billDiscount=Number(state.billDiscount||0);if(state.user)render()},150));
